import Foundation
import CryptoKit

public enum Hashing {
    public static func sha256Hex(_ data: Data) -> String {
        SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }
}

public enum PasteboardSnapshot {
    public static let maxTotalBytes = 25 * 1024 * 1024
    public static let skipMarkers: Set<String> = [
        "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType", "public.file-url",
    ]
    public static let textTypes = ["public.utf8-plain-text", "public.rtf", "public.html"]
    public static let imageTypes = ["public.png", "public.tiff"]

    public static func capture(from pasteboard: PasteboardReading, sourceBundleID: String?) -> CapturedClip? {
        let available = pasteboard.types
        if available.contains(where: skipMarkers.contains) { return nil }

        var reps: [Representation] = []
        var total = 0
        for type in textTypes + imageTypes where available.contains(type) {
            guard let data = pasteboard.data(forType: type) else { continue }
            total += data.count
            if total > maxTotalBytes { return nil }
            reps.append(Representation(type: type, data: data))
        }
        if reps.isEmpty { return nil }

        var plainText: String?
        if let data = reps.first(where: { $0.type == "public.utf8-plain-text" })?.data,
           let s = String(data: data, encoding: .utf8),
           !s.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            plainText = s
        }

        if let text = plainText {
            return CapturedClip(kind: .text, representations: reps, plainText: text,
                                dedupKey: "t:" + Hashing.sha256Hex(Data(text.utf8)),
                                imagePixelSize: nil, sourceBundleID: sourceBundleID)
        }
        guard let image = reps.first(where: { imageTypes.contains($0.type) }) else { return nil }
        return CapturedClip(kind: .image, representations: reps, plainText: nil,
                            dedupKey: "i:" + Hashing.sha256Hex(image.data),
                            imagePixelSize: ImageThumbnail.pixelSize(of: image.data),
                            sourceBundleID: sourceBundleID)
    }
}
